/**
 * Parity tests for src/ndimage against SciPy / OpenCV / NumPy outputs generated by
 * reference/ndimage_fixtures.py (tests/fixtures/ndimage/*.json).
 *
 * Micro-benchmarks run only with NDIMAGE_BENCH=1.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import {
  type Grid,
  type Mask,
  CROSS3,
  binaryClosing,
  binaryDilation,
  binaryErosion,
  binaryFillHoles,
  binaryOpening,
  binaryPropagation,
  disk,
  edt,
  edtIndices,
  externalContour,
  featureTransform,
  fft,
  fft2,
  findExternalContours,
  gaussianFilter,
  gradient,
  irfft2,
  cmul,
  label,
  labelSizes,
  labelSums,
  lstsq,
  mad,
  mapCoordinates,
  maximumFilter,
  median,
  medianFilter,
  medianFilter1d,
  nextFastLen,
  ones,
  percentile,
  resizeArea,
  resizeLinear,
  resizeNearest,
  rfft2,
  rotationMatrix,
  uniformFilter,
  warpAffine,
} from "../src/ndimage/index.js";

const FIX = join(dirname(fileURLToPath(import.meta.url)), "fixtures", "ndimage");
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const load = (name: string): any => JSON.parse(readFileSync(join(FIX, `${name}.json`), "utf8"));

interface FArr { shape: number[]; dtype: string; data: (number | null)[] }

function f64(a: FArr): Grid<Float64Array> {
  const data = Float64Array.from(a.data, (v) => (v === null ? NaN : v));
  return { data, rows: a.shape[0], cols: a.shape[1] ?? data.length };
}
function u8(a: FArr): Mask {
  return { data: Uint8Array.from(a.data as number[]), rows: a.shape[0], cols: a.shape[1] };
}
function i32(a: FArr): Grid<Int32Array> {
  return { data: Int32Array.from(a.data as number[]), rows: a.shape[0], cols: a.shape[1] };
}
function f32(a: FArr): Grid<Float32Array> {
  return { data: Float32Array.from(a.data as number[]), rows: a.shape[0], cols: a.shape[1] };
}

/** max |a - e| / max(max|e|, 1e-300) */
function relErr(actual: ArrayLike<number>, expected: ArrayLike<number | null>): number {
  expect(actual.length).toBe(expected.length);
  let num = 0, den = 0;
  for (let i = 0; i < actual.length; i++) {
    const e = expected[i] ?? NaN;
    const a = actual[i];
    if (Number.isNaN(e) && Number.isNaN(a)) continue;
    num = Math.max(num, Math.abs(a - e));
    den = Math.max(den, Math.abs(e));
    if (Number.isNaN(num)) return Infinity;
  }
  return num / Math.max(den, 1e-300);
}

function expectClose(actual: ArrayLike<number>, expected: ArrayLike<number | null>, tol: number, what = ""): void {
  const err = relErr(actual, expected);
  if (!(err <= tol)) throw new Error(`${what}: relative error ${err.toExponential(3)} > ${tol}`);
}

function expectExact(actual: ArrayLike<number>, expected: ArrayLike<number | null>, what = ""): void {
  expect(actual.length, what).toBe(expected.length);
  for (let i = 0; i < actual.length; i++) {
    if (actual[i] !== expected[i]) {
      throw new Error(`${what}: first mismatch at ${i}: ${actual[i]} != ${expected[i]}`);
    }
  }
}

// --------------------------------------------------------------------------------------- filters
describe("filters (scipy.ndimage)", () => {
  const fx = load("filters");
  const inputs: Record<string, Grid<Float64Array>> = { a: f64(fx.a), b: f64(fx.b) };

  it("gaussian_filter: sigma, anisotropic sigma, derivative orders, truncate", () => {
    let worst = 0;
    for (const c of fx.gaussian) {
      const out = gaussianFilter(inputs[c.input], c.sigma, { order: c.order, truncate: c.truncate });
      const err = relErr(out.data, c.out.data);
      worst = Math.max(worst, err);
      expectClose(out.data, c.out.data, 1e-12, `gaussian ${c.input} s=${c.sigma} o=${c.order}`);
    }
    console.log(`gaussian_filter: ${fx.gaussian.length} cases, worst rel err ${worst.toExponential(2)}`);
  });

  it("gaussian_filter on float32 input reproduces SciPy's float32 rounding", () => {
    const a32: Grid<Float32Array> = { data: Float32Array.from(inputs.a.data), rows: 23, cols: 17 };
    const out = gaussianFilter(a32, 1.0);
    for (let i = 0; i < out.data.length; i++) expect(Math.fround(out.data[i])).toBe(out.data[i]);
  });

  it("uniform_filter", () => {
    for (const c of fx.uniform) expectClose(uniformFilter(inputs[c.input], c.size).data, c.out.data, 1e-12, `uniform ${c.size}`);
  });

  it("maximum_filter (exact)", () => {
    for (const c of fx.maximum) expectExact(maximumFilter(inputs[c.input], c.size).data, c.out.data, `max ${c.size}`);
  });

  it("median_filter 2-D and 1-D (exact)", () => {
    for (const c of fx.median) expectExact(medianFilter(inputs[c.input], c.size).data, c.out.data, `median ${c.size}`);
    const line = f64(fx.line).data;
    for (const c of fx.median1d) expectExact(medianFilter1d(line, c.size), c.out.data, `median1d ${c.size}`);
  });

  it("np.gradient", () => {
    const g = gradient(inputs.a);
    expectExact(g.gy.data, fx.gradient.gy.data, "gy");
    expectExact(g.gx.data, fx.gradient.gx.data, "gx");
    const g2 = gradient(inputs.a, 0.25);
    expectExact(g2.gy.data, fx.gradient.gy_s.data, "gy spacing");
    expectExact(g2.gx.data, fx.gradient.gx_s.data, "gx spacing");
  });
});

// ------------------------------------------------------------------------------------ morphology
describe("binary morphology (scipy.ndimage)", () => {
  const fx = load("morphology");
  const inputs: Record<string, Mask> = Object.fromEntries(Object.entries(fx.inputs).map(([k, v]) => [k, u8(v as FArr)]));
  const structs: Record<string, Mask> = Object.fromEntries(Object.entries(fx.structures).map(([k, v]) => [k, u8(v as FArr)]));

  it("erosion / dilation / opening / closing for cross, square, disk and even structures", () => {
    for (const c of fx.cases) {
      const m = inputs[c.input], st = structs[c.structure], it = c.iterations;
      const tag = `${c.input} ${c.structure} x${it}`;
      expectExact(binaryErosion(m, it, st).data, c.erosion.data, `erosion ${tag}`);
      expectExact(binaryDilation(m, it, st).data, c.dilation.data, `dilation ${tag}`);
      expectExact(binaryOpening(m, it, st).data, c.opening.data, `opening ${tag}`);
      expectExact(binaryClosing(m, it, st).data, c.closing.data, `closing ${tag}`);
    }
  });

  it("default structure is the 4-connected cross", () => {
    const c = fx.cases.find((k: { input: string; structure: string; iterations: number }) => k.input === "m" && k.structure === "cross" && k.iterations === 2);
    expectExact(binaryClosing(inputs.m, 2).data, c.closing.data, "closing default");
    expect(Array.from(CROSS3.data)).toEqual([0, 1, 0, 1, 1, 1, 0, 1, 0]);
  });

  it("1-D closing with a line structure + label", () => {
    const p = u8(fx.plateau);
    for (const c of fx.line) {
      const f = binaryClosing(p, 1, ones(1, 2 * c.gap + 1));
      expectExact(f.data, c.closing.data, `line closing gap ${c.gap}`);
      expectExact(label(f).labels.data, c.label.data, `line label gap ${c.gap}`);
    }
  });

  it("binary_fill_holes", () => {
    for (const [k, v] of Object.entries(fx.fill_holes)) expectExact(binaryFillHoles(inputs[k]).data, (v as FArr).data, `fill ${k}`);
  });

  it("binary_propagation (seed outside the mask is kept)", () => {
    expectExact(binaryPropagation(u8(fx.propagation.seed), inputs.m2).data, fx.propagation.out.data, "prop m2");
    expectExact(binaryPropagation(u8(fx.propagation_ring.seed), inputs.ring).data, fx.propagation_ring.out.data, "prop ring");
  });

  it("disk", () => {
    const d = fx.disk;
    expectExact(disk(d.shape[0], d.shape[1], d.cx, d.cy, d.r).data, d.out.data, "disk");
  });
});

// --------------------------------------------------------------------------------------- measure
describe("label / sum (scipy.ndimage)", () => {
  const fx = load("measure");
  const m = u8(fx.m), vals = f64(fx.vals);
  for (const [name, conn] of [["c4", 4], ["c8", 8]] as const) {
    it(`label connectivity ${conn}`, () => {
      const { labels, n } = label(m, conn);
      expect(n).toBe(fx[name].n);
      expectExact(labels.data, fx[name].labels.data, `labels ${name}`);
      const sums = labelSums(vals, labels, n).subarray(1);
      expectClose(sums, fx[name].sums, 1e-12, `sums ${name}`);
      expectExact(labelSizes(labels, n).subarray(1), fx[name].sizes, `sizes ${name}`);
    });
  }
});

// -------------------------------------------------------------------------------------- distance
describe("distance_transform_edt (scipy.ndimage)", () => {
  const fx = load("distance");
  for (const k of Object.keys(fx).filter((key) => key !== "versions")) {
    it(`distances and nearest indices, ties included (${k})`, () => {
      const m = u8(fx[k].input);
      expectExact(edt(m).data, fx[k].dist.data, `dist ${k}`);
      const { iy, ix } = featureTransform(m);
      expectExact(iy, fx[k].iy.data, `iy ${k}`);
      expectExact(ix, fx[k].ix.data, `ix ${k}`);
      const idx = edtIndices(m);
      for (let i = 0; i < idx.length; i++) expect(idx[i]).toBe(fx[k].iy.data[i] * m.cols + fx[k].ix.data[i]);
    });
  }
});

// ------------------------------------------------------------------------------------ interp
describe("map_coordinates / cv2.resize / cv2.warpAffine", () => {
  const fx = load("interp");

  it("map_coordinates order=1 mode=nearest", () => {
    expectClose(mapCoordinates(f64(fx.a), f64(fx.ys).data, f64(fx.xs).data), fx.map_coordinates.data, 1e-14, "map_coordinates");
  });

  it("resize INTER_AREA / INTER_LINEAR / INTER_NEAREST (non-integer factors, up-scaling)", () => {
    const src = f64(fx.src), srcI = i32(fx.src_i);
    let worst = 0;
    for (const c of fx.resize) {
      const tag = `${c.rows}x${c.cols}`;
      const a = resizeArea(src, c.rows, c.cols).data;
      const l = resizeLinear(src, c.rows, c.cols).data;
      worst = Math.max(worst, relErr(a, c.area.data), relErr(l, c.linear.data));
      expectClose(a, c.area.data, 1e-12, `area ${tag}`);
      expectClose(l, c.linear.data, 1e-12, `linear ${tag}`);
      const nn = resizeNearest(srcI, c.rows, c.cols);
      expect(nn.data).toBeInstanceOf(Int32Array);
      expectExact(nn.data, c.nearest.data, `nearest ${tag}`);
    }
    console.log(`resize: worst rel err ${worst.toExponential(2)}`);
  });

  it("resize integer down-scale (area fast path, 2x linear), float64 and float32", () => {
    const big = f64(fx.big), big32 = f32(fx.big);
    for (const c of fx.fast) {
      const tag = `${c.rows}x${c.cols}`;
      expectClose(resizeArea(big, c.rows, c.cols).data, c.area.data, 1e-12, `area fast ${tag}`);
      expectClose(resizeLinear(big, c.rows, c.cols).data, c.linear.data, 1e-12, `linear ${tag}`);
      expectClose(resizeArea(big32, c.rows, c.cols).data, c.area32.data, 1e-6, `area32 ${tag}`);
    }
  });

  it("getRotationMatrix2D + warpAffine linear (float64, float32) and nearest (int32)", () => {
    const img = f64(fx.img), img32 = f32(fx.img), lab = i32(fx.lab);
    let worst = 0;
    for (const c of fx.rotate) {
      const M = rotationMatrix(c.cx, c.cy, c.angle);
      expectClose(M, c.M, 1e-15, `M ${c.angle}`);
      const tag = `angle ${c.angle}`;
      const lin = warpAffine(img, c.M, 19, 23).data;
      worst = Math.max(worst, relErr(lin, c.linear.data));
      expectClose(lin, c.linear.data, 1e-12, `linear ${tag}`);
      expectClose(warpAffine(img32, c.M, 19, 23).data, c.linear32.data, 1e-6, `linear32 ${tag}`);
      expectClose(warpAffine(img, c.M, 21, 27).data, c.linear_big.data, 1e-12, `linear big ${tag}`);
      const nn = warpAffine(lab, c.M, 19, 23, { nearest: true });
      expect(nn.data).toBeInstanceOf(Int32Array);
      expectExact(nn.data, c.nearest.data, `nearest ${tag}`);
    }
    expectClose(warpAffine(img, fx.extra.scaled.M, 19, 23).data, fx.extra.scaled.linear.data, 1e-12, "scaled");
    expectClose(warpAffine(img, fx.extra.shift.M, 19, 23).data, fx.extra.shift.linear.data, 1e-12, "shift");
    expectExact(warpAffine(lab, fx.extra.shift.M, 19, 23, { nearest: true }).data, fx.extra.shift.nearest.data, "shift nn");
    console.log(`warpAffine: worst rel err ${worst.toExponential(2)}`);
  });
});

// ------------------------------------------------------------------------------------ contours
describe("cv2.findContours RETR_EXTERNAL CHAIN_APPROX_NONE", () => {
  const fx = load("contours");
  it("same contours, same order, same point sequence", () => {
    for (const [i, c] of fx.cases.entries()) {
      const m = u8(c.input);
      expect(findExternalContours(m), `case ${i}`).toEqual(c.contours);
      let longest: number[][] = [];
      for (const k of c.contours as number[][][]) if (k.length > longest.length) longest = k;
      expect(externalContour(m)).toEqual(longest);
    }
  });
});

// ------------------------------------------------------------------------------------------ fft
describe("scipy.fft", () => {
  const fx = load("fft");

  it("next_fast_len (real and complex)", () => {
    const n: number[] = fx.next_fast_len.n;
    expect(n.map((k) => nextFastLen(k, true))).toEqual(fx.next_fast_len.real);
    expect(n.map((k) => nextFastLen(k, false))).toEqual(fx.next_fast_len.complex);
  });

  it("1-D complex FFT for radix-2/3/4/5, small primes and Bluestein lengths", () => {
    for (const [n, c] of Object.entries(fx.fft1d) as [string, { re: number[]; im: number[]; Xre: number[]; Xim: number[] }][]) {
      const re = Float64Array.from(c.re), im = Float64Array.from(c.im);
      fft(re, im);
      const scale = Math.max(...c.Xre.map(Math.abs), ...c.Xim.map(Math.abs));
      for (let k = 0; k < re.length; k++) {
        expect(Math.abs(re[k] - c.Xre[k]) / scale, `n=${n} re[${k}]`).toBeLessThan(1e-12);
        expect(Math.abs(im[k] - c.Xim[k]) / scale, `n=${n} im[${k}]`).toBeLessThan(1e-12);
      }
    }
  });

  it("fft2 (complex)", () => {
    const z = { re: f64(fx.fft2.re).data, im: f64(fx.fft2.im).data, rows: 6, cols: 10 };
    const Z = fft2(z);
    expectClose(Z.re, fx.fft2.Fre.data, 1e-13, "fft2 re");
    expectClose(Z.im, fx.fft2.Fim.data, 1e-13, "fft2 im");
  });

  it("rfft2 / irfft2 with padding shapes, and spectrum products", () => {
    for (const c of fx.rfft2) {
      const s: [number, number] = [c.shape[0], c.shape[1]];
      const a = f64(c.input), b = f64(c.other);
      const F = rfft2(a, s);
      const tag = `${a.rows}x${a.cols}->${s}`;
      expectClose(F.re, c.re.data, 1e-13, `rfft2 re ${tag}`);
      expectClose(F.im, c.im.data, 1e-13, `rfft2 im ${tag}`);
      expectClose(irfft2(F, s).data, c.back.data, 1e-13, `irfft2 ${tag}`);
      // flipped b, as compare.masked_ncc does
      const br: Grid<Float64Array> = { data: new Float64Array(b.data.length), rows: b.rows, cols: b.cols };
      for (let r = 0; r < b.rows; r++) for (let k = 0; k < b.cols; k++) br.data[r * b.cols + k] = b.data[(b.rows - 1 - r) * b.cols + (b.cols - 1 - k)];
      const G = rfft2(br, s);
      expectClose(irfft2(cmul(F, G), s).data, c.corr.data, 1e-13, `corr ${tag}`);
    }
  });
});

// ------------------------------------------------------------------------------- linalg / stats
describe("lstsq / percentile / median / mad (numpy)", () => {
  const fx = load("linalg");
  it("lstsq (full rank, square, rank deficient min-norm)", () => {
    for (const c of fx.lstsq) {
      const x = lstsq(f64(c.A), c.b);
      expectClose(x, c.x, c.rank_deficient ? 1e-9 : 1e-11, `lstsq ${c.A.shape}`);
    }
  });
  it("percentile (linear), median, mad", () => {
    for (const c of fx.stats) {
      const p = percentile(c.v, c.q as number[]);
      for (let i = 0; i < p.length; i++) expect(p[i], `n=${c.v.length} q=${c.q[i]}`).toBe(c.p[i]);
      expect(median(c.v)).toBe(c.median);
      expect(mad(c.v)).toBe(c.mad);
    }
  });
});

// ------------------------------------------------------------------------------------- bench
describe.skipIf(!process.env.NDIMAGE_BENCH)("micro-benchmarks (NDIMAGE_BENCH=1)", () => {
  const N = 1200;
  const img: Grid<Float64Array> = { data: new Float64Array(N * N), rows: N, cols: N };
  let s = 12345;
  for (let i = 0; i < img.data.length; i++) {
    s = (s * 1103515245 + 12345) % 2147483648;
    img.data[i] = s / 2147483648;
  }
  const time = (label: string, fn: () => unknown, reps = 3): void => {
    fn();
    const t0 = performance.now();
    for (let i = 0; i < reps; i++) fn();
    console.log(`${label}: ${((performance.now() - t0) / reps).toFixed(1)} ms`);
  };
  it("gaussianFilter 1200x1200", () => {
    for (const sigma of [0.7, 1, 3, 8, 20]) time(`gaussianFilter sigma=${sigma}`, () => gaussianFilter(img, sigma));
    time("gaussianFilter sigma=3 order [0,1]", () => gaussianFilter(img, 3, { order: [0, 1] }));
  });
  it("other ops 1200x1200", () => {
    const m: Mask = { data: Uint8Array.from(img.data, (v) => (v < 0.97 ? 1 : 0)), rows: N, cols: N };
    time("edt", () => edt(m));
    time("binaryClosing x3 (cross)", () => binaryClosing(m, 3));
    time("binaryOpening disk r=3", () => binaryOpening(m, 1, disk(7, 7, 3, 3, 3)));
    time("binaryFillHoles", () => binaryFillHoles(m));
    time("label", () => label(m));
    time("uniformFilter 9", () => uniformFilter(img, 9));
    time("resizeArea 1200->517", () => resizeArea(img, 517, 517));
    time("warpAffine linear", () => warpAffine(img, rotationMatrix(600, 600, 17), N, N));
    time("rfft2+irfft2 1200x1200 -> 2400x2400", () => irfft2(rfft2(img, [2400, 2400]), [2400, 2400]), 1);
    time("percentile 1.44M", () => percentile(img.data, 99), 3);
  });
});
